# 统计每行非零元素的均值
def mean_ignore_zeros(tensor):
    nonzero_mask = tensor != 0
    lengths = nonzero_mask.sum(dim=-1)
    sums = tensor.sum(dim=-1)
    means = sums / lengths.clamp(min=1)
    return means

